# === G1 CLIMB v2: このセル1つで全部やります(失敗時はログ末尾を自動表示) ===
import base64, os, subprocess, sys

r = subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True)
assert r.returncode == 0 and r.stdout.strip(), \
    "GPUがありません: メニュー[ランタイム→ランタイムのタイプを変更→T4 GPU]を選んで再実行"
print(r.stdout.strip()); print("✅ GPU OK")

os.system(f"{sys.executable} -m pip install -q playground 'jax[cuda12]'")
import jax; print("JAX devices:", jax.devices())

open("g1_climb_mjx_env.py", "wb").write(base64.b64decode(""))
open("g1_train_colab.py", "wb").write(base64.b64decode(""))
print("✅ ファイル展開OK — スモークテスト→学習(1〜2時間)。チェックポイントは毎評価ごとに保存")

rc = os.system(f"{sys.executable} g1_train_colab.py --task climb "
               f"--steps 150_000_000 --out /content/g1_climb 2>&1 | tee /content/train.log")
if rc != 0:
    print("\n===== 学習が異常終了: ログ末尾(これを貼って報告してください) =====")
    print("".join(open("/content/train.log").readlines()[-50:]))
    raise SystemExit("training failed — 上のログを報告")

# 成果物一式をzipしてダウンロード(params + 毎評価チェックポイント + メトリクス + ログ)
os.system("cd /content && zip -q -r g1_climb_artifacts.zip "
          "g1_climb_params.pkl g1_climb_config.json g1_climb_best_params.pkl "
          "g1_climb_metrics.jsonl train.log g1_climb_ckpt_*.pkl")
from google.colab import files
files.download("/content/g1_climb_artifacts.zip")
print("🎉 完了 — g1_climb_artifacts.zip を Mac へ(中の params.pkl を models/policies/ に)")
